binaries={v:f'/tmp/fieldkin-kernels-{v}' for v in ['before','after']}
report={'platform':platform.platform(),'cpu_affinity':[cpu],'started_utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'binary_sha256':{v:hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest() for v,p in binaries.items()},'input_sha256':{name:hashlib.sha256(path.read_bytes()).hexdigest() for name,path in cases.items()},'runs':[],'failures':[]}
expected={}; destination=pathlib.Path('/tmp/fieldkin-coma-kernels-pinned-results.json')
for round in range(3):
 for name,path in cases.items():
  for version in (['before','after'] if round%2==0 else ['after','before']):
   record=dict(round=round,case=name,version=version)
   try:
    lines=subprocess.check_output([binaries[version],'dataset_instances','0','11',str(path)],cwd=root,text=True,timeout=90).splitlines()
    assert len(lines)==3,(name,len(lines))
    times=json.loads(lines[0]);assert len(times)==11
    digest=hashlib.sha256(lines[2].encode()).hexdigest()
    assert expected.setdefault(name,digest)==digest,(name,version,'changed score/details/order')
    record.update(times_ms=times,median_ms=statistics.median(times),peak_rss_kib=int(lines[1].split()[0]),output_sha256=digest)
   except Exception as error:
    record['error']=str(error);report['failures'].append(record)
   report['runs'].append(record);destination.write_text(json.dumps(report,indent=2)+'\n')
 print('round',round+1,'done',flush=True)
for case in cases:
 rows=[r for r in report['runs'] if r['case']==case and 'median_ms' in r]
 if len(rows)!=6: print(case,'incomplete');continue
 m={v:statistics.median(r['median_ms'] for r in rows if r['version']==v) for v in binaries}
 print(case,m,'change%',100*(m['after']/m['before']-1),flush=True)
if report['failures']: raise SystemExit(1)

