use std::{hint::black_box, time::Instant};
fn old(a:&str,b:&str)->f64 {strsim::normalized_levenshtein(a,b)}
fn new(a:&str,b:&str)->f64 {rapidfuzz::distance::levenshtein::normalized_similarity(a.chars(),b.chars())}
fn main() {
 let cases=[("short", "abc".to_owned(), "abd".to_owned(), 20000),
  ("short_unicode", "é界🙂".to_owned(), "é海🙃".to_owned(), 20000),
  ("equal", "account_identifier".repeat(4), "account_identifier".repeat(4), 5000),
  ("ascii64", "abcxyz12".repeat(8), "qwyabc92".repeat(8), 500),
  ("unicode64", "é界🙂a".repeat(16), "海🙃éa".repeat(16), 500),
  ("unequal", "id".to_owned(), "customer_identifier".repeat(8), 3000),
  ("long_prefix", "a".repeat(1024)+"b", "a".repeat(1024)+"c", 25),
  ("long_unrelated", "a".repeat(256), "x".repeat(256), 100)];
 for (name,a,b,repeats) in cases {
  assert_eq!(old(&a,&b).to_bits(),new(&a,&b).to_bits());
  let mut before=Vec::new();let mut after=Vec::new();
  for round in 0..5 {
   let versions = if round%2==0 {[(old as fn(&str,&str)->f64,&mut before),(new,&mut after)]} else {[(new as fn(&str,&str)->f64,&mut after),(old,&mut before)]};
   for (run,times) in versions {
    black_box(run(&a,&b));
    let start=Instant::now();
    for _ in 0..repeats {black_box(run(black_box(&a),black_box(&b)));}
    times.push(start.elapsed().as_secs_f64()*1000.0);
   }
  }
  println!("{name} {repeats} before={before:?} after={after:?}");
 }
}

