fn main() {
    let mut strings = vec![String::new()];
    let mut generation = vec![String::new()];
    for _ in 0..5 {
        generation = generation.iter().flat_map(|s| ['a', 'é', '界'].map(move |c| format!("{s}{c}"))).collect();
        strings.extend(generation.clone());
    }
    strings.extend(["\0", "a\0b", "İ", "i\u{307}", "e\u{301}", "é", "ΣΟΣ", "σος", "🙂🙃🙂"].map(str::to_owned));
    let mut compared = 0;
    for a in &strings { for b in &strings {
        let old = strsim::normalized_levenshtein(a, b);
        let new = rapidfuzz::distance::levenshtein::normalized_similarity(a.chars(), b.chars());
        assert_eq!(old.to_bits(), new.to_bits(), "{a:?}, {b:?}"); compared += 1;
    }}
    for len in [31,32,33,63,64,65,127,128,129,255,256,257] {
        for alphabet in ["abcdefg", "é界🙂\0e\u{301}"] {
            let a: String = alphabet.chars().cycle().take(len).collect();
            let candidates = [a.clone(), a.chars().rev().collect(), format!("{a}Z"), format!("Z{a}"), "xyz".chars().cycle().take(len).collect(), a.chars().skip(3).collect()];
            for b in candidates {
                let old = strsim::normalized_levenshtein(&a, &b);
                let new = rapidfuzz::distance::levenshtein::normalized_similarity(a.chars(), b.chars());
                assert_eq!(old.to_bits(), new.to_bits(), "{len}: {a:?}, {b:?}"); compared += 1;
            }
        }
    }
    println!("{compared} exact bit comparisons passed");
}
